begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select has_table('public','warranty_cases','warranty storage exists');
insert into public.organizations(id,name,slug) values('a2600000-0000-4000-8000-000000000001','Warranty fixture','warranty-026');
insert into auth.users(id) values('b2600000-0000-4000-8000-000000000001');
insert into public.staff_profiles(user_id,organization_id,role) values('b2600000-0000-4000-8000-000000000001','a2600000-0000-4000-8000-000000000001','staff');
insert into public.conversations(id,organization_id,page_id,psid) values('a2600000-0000-4000-8000-000000000026','a2600000-0000-4000-8000-000000000001','260','warranty-fixture');
insert into public.products(id,organization_id,source_name,source_url,canonical_url,name,in_stock,quality) values('c2600000-0000-4000-8000-000000000001','a2600000-0000-4000-8000-000000000001','fixture','urn:warranty:fixture','urn:warranty:fixture','Fixture laptop',true,'partial');
insert into public.orders(id,organization_id,created_by_kind,created_by_actor_id,buyer_name,subtotal_vnd,conversation_id) values('d2600000-0000-4000-8000-000000000001','a2600000-0000-4000-8000-000000000001','staff','b2600000-0000-4000-8000-000000000001','Synthetic buyer',100000,'a2600000-0000-4000-8000-000000000026');
insert into public.order_items(order_id,line_number,product_id,product_version,name,quantity,unit_price_vnd,line_total_vnd) values('d2600000-0000-4000-8000-000000000001',1,'c2600000-0000-4000-8000-000000000001',1,'Fixture laptop',1,100000,100000);
create function pg_temp.save_case(ver integer,stage text default 'RECEIVED',req uuid default gen_random_uuid(),line integer default 1) returns jsonb language sql as $$select public.save_warranty_case('a2600000-0000-4000-8000-000000000001','b2600000-0000-4000-8000-000000000001','e2600000-0000-4000-8000-000000000001',req,ver,'d2600000-0000-4000-8000-000000000001',line,stage,'Customer progress','PRIVATE staff note')$$;
select throws_ok($$select pg_temp.save_case(0)$$,'22023','WARRANTY_INELIGIBLE','unpaid draft cannot become warranty');
update public.orders set checkout_frozen_at=now(),checkout_snapshot='{}',checkout_request_id=gen_random_uuid(),payment_status='PAID',fulfilment_status='DELIVERED' where id='d2600000-0000-4000-8000-000000000001';
set local role service_role;
select throws_ok($$select pg_temp.save_case(0,'RECEIVED',gen_random_uuid(),2)$$,'22023','WARRANTY_INELIGIBLE','item must belong to order');
select lives_ok($$select pg_temp.save_case(0,'RECEIVED','f2600000-0000-4000-8000-000000000001')$$,'staff manually creates case');
select lives_ok($$select pg_temp.save_case(0,'RECEIVED','f2600000-0000-4000-8000-000000000001')$$,'same request replay');
select is((select count(*) from public.warranty_history where case_id='e2600000-0000-4000-8000-000000000001'),1::bigint,'retry produces one history');
select throws_ok($$select pg_temp.save_case(0)$$,'40001','WARRANTY_CONFLICT','version conflict');
select throws_ok($$select pg_temp.save_case(1,'READY')$$,'22023','WARRANTY_TRANSITION','cannot skip stages');
select lives_ok($$select pg_temp.save_case(1,'INSPECTING')$$,'next status permitted');
select lives_ok($$select pg_temp.save_case(2,'INSPECTING')$$,'same-stage note update permitted');
select throws_ok($$select pg_temp.save_case(3,'RECEIVED')$$,'22023','WARRANTY_TRANSITION','cannot go backwards');
select throws_ok($$select pg_temp.save_case(0,'INSPECTING','f2600000-0000-4000-8000-000000000001')$$,'40001','WARRANTY_CONFLICT','request payload cannot change');
select throws_ok($$select pg_temp.save_case(3,'INSPECTING',gen_random_uuid(),2)$$,'42501','WARRANTY_FORBIDDEN','existing case cannot switch order item');
select is(public.read_staff_warranty('a2600000-0000-4000-8000-000000000001','b2600000-0000-4000-8000-000000000001')->>'total','1','staff reads scoped case list');
select is(public.read_staff_warranty('a2600000-0000-4000-8000-000000000001','b2600000-0000-4000-8000-000000000001')->'items'->0->'history','[]'::jsonb,'list omits expanded history');
select is(public.read_staff_warranty('a2600000-0000-4000-8000-000000000001','b2600000-0000-4000-8000-000000000001','e2600000-0000-4000-8000-000000000001')->>'privateNote','PRIVATE staff note','staff detail includes private notes');
select is(public.read_staff_warranty('a2600000-0000-4000-8000-000000000001','b2600000-0000-4000-8000-000000000001',null,'Fixture',1,true)->0->>'productName','Fixture laptop','eligible order search uses product label');
select is(jsonb_array_length(public.read_customer_warranty('a2600000-0000-4000-8000-000000000001','a2600000-0000-4000-8000-000000000026','d2600000-0000-4000-8000-000000000001')),1,'bound conversation can read progress');
select ok(public.read_customer_warranty('a2600000-0000-4000-8000-000000000001','a2600000-0000-4000-8000-000000000026','d2600000-0000-4000-8000-000000000001')::text not like '%PRIVATE%','customer response and history exclude private notes');
select is(public.read_customer_warranty('a2600000-0000-4000-8000-000000000001',gen_random_uuid(),'d2600000-0000-4000-8000-000000000001'),'[]'::jsonb,'different customer conversation blocked');
select is(public.read_customer_warranty(gen_random_uuid(),'a2600000-0000-4000-8000-000000000026','d2600000-0000-4000-8000-000000000001'),'[]'::jsonb,'foreign organization progress blocked');
select is(public.read_customer_warranty('a2600000-0000-4000-8000-000000000001','a2600000-0000-4000-8000-000000000026',gen_random_uuid()),'[]'::jsonb,'case outside requested order blocked');
select is(public.read_customer_warranty('a2600000-0000-4000-8000-000000000001',null,'d2600000-0000-4000-8000-000000000001'),'[]'::jsonb,'unknown conversation fails closed');
select lives_ok($$select pg_temp.save_case(3,'IN_SERVICE')$$,'service transition');
select lives_ok($$select pg_temp.save_case(4,'READY')$$,'ready transition');
select lives_ok($$select pg_temp.save_case(5,'COMPLETED')$$,'complete transition');
select throws_ok($$select pg_temp.save_case(6,'READY')$$,'22023','WARRANTY_TRANSITION','completed case cannot reopen');
reset role;
select throws_ok($$update public.warranty_history set customer_note='changed' where case_id='e2600000-0000-4000-8000-000000000001'$$,'55000',null,'history immutable');
select ok(not has_table_privilege('anon','public.warranty_cases','SELECT'),'anonymous cannot read cases');
select ok(not has_table_privilege('authenticated','public.warranty_history','SELECT'),'browser cannot read private history');
select ok(not has_table_privilege('service_role','public.warranty_cases','UPDATE'),'service cannot bypass audited writer');
select is((select count(*) from public.audit_events where action='warranty.saved' and organization_id='a2600000-0000-4000-8000-000000000001'),6::bigint,'every successful version audited');
create function pg_temp.reject_warranty_audit() returns trigger language plpgsql as $$begin raise exception 'warranty_audit_failure'; end$$;
create trigger warranty_audit_fixture before insert on public.audit_events for each row execute function pg_temp.reject_warranty_audit();
select throws_ok($$select pg_temp.save_case(6,'COMPLETED')$$,'P0001','warranty_audit_failure','audit failure rolls back save');
select is((select version from public.warranty_cases where id='e2600000-0000-4000-8000-000000000001'),6,'case unchanged on audit failure');
select is((select count(*) from public.warranty_history where case_id='e2600000-0000-4000-8000-000000000001'),6::bigint,'history rollback is atomic');
update public.staff_profiles set active=false where user_id='b2600000-0000-4000-8000-000000000001';
select throws_ok($$select pg_temp.save_case(0,'RECEIVED','f2600000-0000-4000-8000-000000000001')$$,'42501','WARRANTY_FORBIDDEN','disabled staff cannot replay');
select throws_ok($$select public.read_staff_warranty('a2600000-0000-4000-8000-000000000001','b2600000-0000-4000-8000-000000000001')$$,'42501','WARRANTY_FORBIDDEN','disabled staff cannot read');
select * from finish();
rollback;
